-- Hardcore Logistics runtime mod (UE4SS Lua).
--
-- Applies the changes listed in edits.lua (generated by tools/build_mod.py from mod_config.json) to the game's
-- data tables in memory, per feature and per world. Each feature (for example "cargo", "deliveries") is one
-- Off / On row in the game's playstyle settings (see ui.lua).
--
-- When changes apply: a world runs with the features it was loaded with. Table features are applied just before the
-- world loads (load-map pre hook, for the save slot the game instance is about to load), because the game's delivery
-- system copies the delivery table while a world loads. Changing one in a loaded world (settings row or console) is
-- saved for that world and applies the next time it loads. The tables stay in memory for the whole session (the game
-- instance class references them), so editing them between worlds is safe. Live features (crop trampling, see
-- trample.lua; local storage, see storage.lua) are scripts: switching one in a loaded world is saved and applies at
-- once. A live feature can also own tables (local storage: the storage sizes, DT_StorageCapacities; and the Logistics
-- Hub, which tools/build_buildings.py ships hidden: its DT_Constructs flag and its DT_DeliveryMilestones reward); those
-- apply like any table, before the world loads, so after a switch in a loaded world they follow on the next load.
-- A table change is a number (values), a map rewritten (maps: a cost list), a name field set (names: a FeatureFlag's
-- TagName) or names added to an array of names (lists: a milestone's ConstructRewards); each is undone for worlds
-- without its feature.
--
-- worlds.txt: one line per save slot listing the features that are on (World_3=cargo,deliveries / World_4=off).
-- An older "World_3=on" line means every feature.
--
-- Console (~ or F10):   hardcore                       status
--                       hardcore on | off              every feature, for the loaded world
--                       hardcore <feature> on | off    one feature
--                       hardcore check                 what the game is using right now
--                       hardcore timing [reset]        how long each script loop's runs take
--                       hardcore mounds                the mounds around each mech (trample.lua)
--                       hardcore sound [name]          play the crush sound at your mech; a name switches it
--                       hardcore storages              the storages in each base and which count right now (storage.lua)
--                       hardcore hub [unlock]          the Logistics Hubs: unlocks and the hubs placed (storage.lua)
--                       hardcore unlock [all | row]    the mod's buildings: unlock state; unlock them now (unlocks.lua)
--                       hardcore drones                the Drone Stations by paint colour and their drones (drones.lua)

local MOD = "[HardcoreLogistics] "
local function log(msg) print(MOD .. msg .. "\n") end

-- Repeating and delayed work runs on the game thread only. LoopAsync and ExecuteWithDelay run their callback on a
-- second thread, which then queues the real work with ExecuteInGameThread. That second thread runs Lua in the same
-- Lua state while the game thread is running our scripts. On 2026-11-09 (0.8.2) the game crashed inside UE4SS's
-- FindAllOf: its first argument, a constant class-name string, read as NULL, so the Lua stack had changed under it.
-- This UE4SS build has game-thread timers (LoopInGameThreadWithDelay, ExecuteInGameThreadWithDelay, driven by the
-- engine tick), so the old pattern is only a fallback for builds without them.
--
-- Every loop is timed: these callbacks run inside a game frame, so a slow one shows up as a stutter at its interval.
-- A run of SLOW_MS or more is logged (at most every 10 s per loop); "hardcore timing" lists every loop. Work started
-- by a hook rather than a loop reports itself through api.recordTiming(what, ms).
local SLOW_MS = 8
local loopStats = {}            -- {what, every, runs, total, max, last, slow, lastWarn}, in the order they start

local function recordTiming(what, dt)
    local st = nil
    for _, s in ipairs(loopStats) do
        if s.what == what then st = s end
    end
    if not st then
        st = { what = what, every = 0, runs = 0, total = 0, max = 0, last = 0, slow = 0, lastWarn = -math.huge }
        loopStats[#loopStats + 1] = st
    end
    st.runs, st.total, st.last = st.runs + 1, st.total + dt, dt
    if dt > st.max then st.max = dt end
    if dt >= SLOW_MS then
        st.slow = st.slow + 1
        local now = os.clock()
        if now - st.lastWarn >= 10 then
            st.lastWarn = now
            log(string.format("timing: %s took %.1f ms (%d of %d runs took %d ms or more so far)", what, dt, st.slow,
                st.runs, SLOW_MS))
        end
    end
end
local function gameLoop(ms, what, fn)
    local st = { what = what, every = ms, runs = 0, total = 0, max = 0, last = 0, slow = 0, lastWarn = -math.huge }
    loopStats[#loopStats + 1] = st
    local function run()
        local t0 = os.clock()
        local ok, err = pcall(fn)
        local dt = (os.clock() - t0) * 1000
        st.runs, st.total, st.last = st.runs + 1, st.total + dt, dt
        if dt > st.max then st.max = dt end
        if dt >= SLOW_MS then
            st.slow = st.slow + 1
            if t0 - st.lastWarn >= 10 then
                st.lastWarn = t0
                log(string.format("timing: %s took %.1f ms (%d of %d runs took %d ms or more so far; hardcore timing "
                    .. "lists every loop)", what, dt, st.slow, st.runs, SLOW_MS))
            end
        end
        if not ok then log(what .. " failed: " .. tostring(err)) end
    end
    if type(LoopInGameThreadWithDelay) == "function" then
        local ok, handle = pcall(LoopInGameThreadWithDelay, ms, run)
        if ok then return handle end
        log(what .. ": no game-thread timer (" .. tostring(handle) .. "), using LoopAsync")
    end
    LoopAsync(ms, function()
        ExecuteInGameThread(run)
        return false
    end)
    return nil
end

local function gameDelay(ms, fn)
    if type(ExecuteInGameThreadWithDelay) == "function" and pcall(ExecuteInGameThreadWithDelay, ms, fn) then return end
    ExecuteWithDelay(ms, function() ExecuteInGameThread(fn) end)
end

local scriptDir = (debug.getinfo(1, "S").source:gsub("^@", "")):match("^(.*)[/\\]") or "."
local WORLDS_FILE = scriptDir .. "/../worlds.txt"
local SAVE_DIR = (os.getenv("LOCALAPPDATA") or "") .. "\\FarMech\\Saved\\SaveGames\\"

local okEdits, EDITS = pcall(dofile, scriptDir .. "/edits.lua")
if not okEdits or type(EDITS) ~= "table" then
    log("could not load edits.lua: " .. tostring(EDITS))
    return
end

local FEATURES = EDITS.features or {}      -- {id, label, live}, in settings-row order
local FEATURE = {}
for _, f in ipairs(FEATURES) do FEATURE[f.id] = f end
local OWNS_TABLES = {}                     -- feature id -> true when edits.lua lists a table for it
for _, t in ipairs(EDITS.tables or {}) do OWNS_TABLES[t.feature] = true end
for _, f in ipairs(FEATURES) do f.tables = OWNS_TABLES[f.id] == true end    -- ui.lua: a reload line for these too

local function isLive(fid) return FEATURE[fid] ~= nil and FEATURE[fid].live == true end

-- ------------------------------------------------------------------ helpers

local function asText(v)
    if v == nil then return nil end
    if type(v) == "string" then return v end
    if type(v) == "userdata" then
        local ok, s = pcall(function() return v:ToString() end)
        if ok and s ~= nil then return tostring(s) end
    end
    return tostring(v)
end

local function makeName(s)
    local ok, n = pcall(function() return FName(s, EFindName.FNAME_Add) end)
    if ok and n then return n end
    return FName(s)
end

local function addressOf(obj)
    local ok, a = pcall(function() return obj:GetAddress() end)
    return ok and a or nil
end

local function hex(a)
    if type(a) == "number" then return string.format("0x%X", a) end
    return tostring(a)
end

-- feature sets: {id = true} for the features that are on
local function allFeatures()
    local s = {}
    for _, f in ipairs(FEATURES) do s[f.id] = true end
    return s
end

local function copySet(s)
    local c = {}
    for k, v in pairs(s or {}) do if v then c[k] = true end end
    return c
end

local function describe(set)
    local parts = {}
    for _, f in ipairs(FEATURES) do parts[#parts + 1] = f.id .. " " .. ((set and set[f.id]) and "ON" or "off") end
    return table.concat(parts, ", ")
end

-- ------------------------------------------------------------------ worlds.txt

local unknownLogged = {}

local function parseFeatures(value)
    local v = value:lower()
    if v == "on" then return allFeatures() end
    local set = {}
    if v == "off" or v == "none" or v == "" then return set end
    for id in v:gmatch("[^,%s]+") do
        if FEATURE[id] then
            set[id] = true
        elseif not unknownLogged[id] then
            unknownLogged[id] = true
            log("worlds.txt names an unknown feature '" .. id .. "'; known: " .. describe(allFeatures()))
        end
    end
    return set
end

local function readWorlds()
    local worlds = {}
    local f = io.open(WORLDS_FILE, "r")
    if f then
        for line in f:lines() do
            local slot, value = line:match("^%s*([^#=%s][^=]-)%s*=%s*(.-)%s*$")
            if slot then worlds[slot] = parseFeatures(value) end
        end
        f:close()
    end
    return worlds
end

local function writeWorlds(worlds)
    local f = io.open(WORLDS_FILE, "w")
    if not f then log("cannot write " .. WORLDS_FILE); return end
    local ids = {}
    for _, feat in ipairs(FEATURES) do ids[#ids + 1] = feat.id end
    f:write("# Hardcore Logistics: one line per world save slot, listing the features that are on, or off.\n")
    f:write("# Features: " .. table.concat(ids, ", ") .. ". Example: World_3=" .. table.concat(ids, ",") .. "\n")
    f:write("# Change them with the settings rows or the console command  hardcore <feature> on|off.\n")
    local keys = {}
    for k in pairs(worlds) do keys[#keys + 1] = k end
    table.sort(keys)
    for _, k in ipairs(keys) do
        local on = {}
        for _, feat in ipairs(FEATURES) do if worlds[k][feat.id] then on[#on + 1] = feat.id end end
        f:write(k .. "=" .. (#on > 0 and table.concat(on, ",") or "off") .. "\n")
    end
    f:close()
end

local function saveExists(slot)
    local f = io.open(SAVE_DIR .. slot .. ".sav", "rb")
    if f then f:close(); return true end
    return false
end

-- ------------------------------------------------------------------ which world is loaded

local SLOT_SOURCES = { "SaveSlotManager", "BP_SaveSlotManager_C", "SaveLoadComponent", "SaveLoadComponent_C",
                       "FarMechGameInstance", "BP_FarMechGameInstance_C" }
local slotSourceLogged = false

-- the slot of the world that is loaded right now (nil in menus)
local function getActiveSlot()
    for _, cls in ipairs(SLOT_SOURCES) do
        local okFind, obj = pcall(FindFirstOf, cls)
        if okFind and obj and obj:IsValid() then
            local okCall, res = pcall(function() return obj:GetActiveSaveSlot() end)
            local slot = okCall and asText(res) or nil
            if slot and slot ~= "" then
                if not slotSourceLogged then
                    log("active save slot read from " .. cls .. ":GetActiveSaveSlot()")
                    slotSourceLogged = true
                end
                return slot
            end
        end
    end
    return nil
end

-- the slot the game instance is set to; when a world is about to load, the slot of that world
local function gameInstanceSlot()
    local okFind, gi = pcall(FindFirstOf, "BP_FarMechGameInstance_C")
    if not okFind or not gi or not gi:IsValid() then return nil end
    local ok, s = pcall(function() return asText(gi.WorldSaveSlot) end)
    if ok and s and s ~= "" then return s end
    return nil
end

local function diagnoseSlot()
    log("could not read the active save slot; properties that might hold it:")
    for _, cls in ipairs(SLOT_SOURCES) do
        local okFind, obj = pcall(FindFirstOf, cls)
        if okFind and obj and obj:IsValid() then
            log("  " .. obj:GetFullName())
            pcall(function()
                local class = obj:GetClass()
                while class and class:IsValid() do
                    class:ForEachProperty(function(prop)
                        local name = prop:GetFName():ToString()
                        if name:find("Slot") or name:find("World") or name:find("Save") then
                            local okV, v = pcall(function() return obj[name] end)
                            log(string.format("    %s %s = %s", prop:GetClass():GetFName():ToString(), name,
                                tostring(okV and asText(v) or "?")))
                        end
                    end)
                    class = class:GetSuperStruct()
                end
            end)
        end
    end
end

-- ------------------------------------------------------------------ applying edits

local function findTable(path, allowLoad)
    local dt = StaticFindObject(path)
    if (not dt or not dt:IsValid()) and allowLoad then
        pcall(LoadAsset, path)
        dt = StaticFindObject(path)
    end
    if not dt or not dt:IsValid() then return nil end
    return dt
end

local function loadRows(path)
    local dt = findTable(path, true)
    if not dt then return nil, "table not found: " .. path end
    local rows = {}
    for _, entry in ipairs(dt:GetAllRows()) do
        rows[asText(entry.Name)] = entry.Data
    end
    return rows, nil, dt
end

-- Follow steps from edits.lua: {"field", name} | {"select", field, inner, text} | {"index", i}
local function walk(node, steps, upto)
    for i = 1, upto do
        local s = steps[i]
        if s[1] == "field" then
            node = node[s[2]]
        elseif s[1] == "select" then
            local field, inner, want = s[2], s[3], s[4]
            local found = nil
            node:ForEach(function(_, elem)
                if found then return end
                local item = elem:get()
                local v = item[field]
                if inner ~= "" then v = v[inner] end
                if asText(v) == want then found = item end
            end)
            if not found then return nil, "no element with " .. field .. " = " .. want end
            node = found
        elseif s[1] == "index" then
            node = node[s[2] + 1]
        else
            return nil, "unsupported step " .. tostring(s[1])
        end
        if node == nil then return nil, "missing " .. tostring(s[2]) end
    end
    return node
end

local function mapEntries(map)
    local list = {}
    local ok = pcall(function()
        map:ForEach(function(k, v) list[#list + 1] = { asText(k:get()), v:get() } end)
    end)
    return ok and list or nil
end

local function setMap(map, entries)
    map:Empty()
    for _, kv in ipairs(entries) do map:Add(makeName(kv[1]), kv[2]) end
end

local function formatEntries(list)
    local parts = {}
    for _, kv in ipairs(list or {}) do parts[#parts + 1] = kv[1] .. "=" .. tostring(kv[2]) end
    return "{" .. table.concat(parts, ", ") .. "}"
end

-- the names in an array of names (a row's ConstructRewards), as text: a UE4SS TArray (ForEach, elements read with
-- :get()), or a plain Lua list (what this script wrote there before)
local function nameList(arr)
    local list = {}
    if type(arr) == "userdata" or (type(arr) == "table" and arr.ForEach ~= nil) then
        arr:ForEach(function(_, e) list[#list + 1] = asText(e:get()) end)
    else
        for i, v in ipairs(arr) do list[i] = asText(v) end
    end
    return list
end

-- write an array of names from a list of texts (UE4SS sets an array property from a Lua table)
local function setNameList(parent, field, list)
    local names = {}
    for i, s in ipairs(list) do names[i] = makeName(s) end
    parent[field] = names
end

-- applied[f]: feature f's changes are in the tables; undo[f]: list of {path, fn}; tables[path]: address of the
-- table object the undo entries point into
local state = { applied = {}, undo = {}, tables = {} }

local function applyFeature(fid)
    local undo, done, failed, notes, where = {}, 0, 0, 0, {}
    for _, t in ipairs(EDITS.tables) do
        if t.feature == fid then
            local rows, err, dt = loadRows(t.path)
            if not rows then
                log(err)
                failed = failed + #(t.values or {}) + #(t.maps or {}) + #(t.names or {}) + #(t.lists or {})
            else
                state.tables[t.path] = addressOf(dt) or "unknown"
                where[#where + 1] = t.name .. " " .. hex(state.tables[t.path])
                for _, e in ipairs(t.values or {}) do
                    local ok, msg = pcall(function()
                        local data = rows[e.row]
                        if not data then error("row not found") end
                        local parent, werr = walk(data, e.steps, #e.steps - 1)
                        if not parent then error(werr) end
                        local field = e.steps[#e.steps][2]
                        local before = parent[field]
                        if math.abs((tonumber(before) or 0) - e.vanilla) > 1e-3 and notes < 10 then
                            notes = notes + 1
                            log(string.format("note: %s %s was %s, expected vanilla %s", t.name, e.row, tostring(before), tostring(e.vanilla)))
                        end
                        parent[field] = e.value
                        undo[#undo + 1] = { t.path, function() parent[field] = before end }
                    end)
                    if ok then done = done + 1 else failed = failed + 1; log(string.format("failed %s %s: %s", t.name, e.row, tostring(msg))) end
                end
                for _, m in ipairs(t.maps or {}) do
                    local ok, msg = pcall(function()
                        local data = rows[m.row]
                        if not data then error("row not found") end
                        local map, werr = walk(data, m.steps, #m.steps)
                        if not map then error(werr) end
                        local before = mapEntries(map) or m.vanilla
                        setMap(map, m.target)
                        undo[#undo + 1] = { t.path, function() setMap(map, before) end }
                    end)
                    if ok then done = done + 1 else failed = failed + 1; log(string.format("failed %s %s: %s", t.name, m.row, tostring(msg))) end
                end
                -- a name field set to another name (a building's FeatureFlag.TagName: Features.Legacy hides it)
                for _, n in ipairs(t.names or {}) do
                    local ok, msg = pcall(function()
                        local data = rows[n.row]
                        if not data then error("row not found") end
                        local parent, werr = walk(data, n.steps, #n.steps - 1)
                        if not parent then error(werr) end
                        local field = n.steps[#n.steps][2]
                        local before = asText(parent[field])
                        if before ~= n.vanilla and notes < 10 then
                            notes = notes + 1
                            log(string.format("note: %s %s was %s, expected %s", t.name, n.row, tostring(before), n.vanilla))
                        end
                        parent[field] = makeName(n.value)
                        undo[#undo + 1] = { t.path, function() parent[field] = makeName(before) end }
                    end)
                    if ok then done = done + 1 else failed = failed + 1; log(string.format("failed %s %s: %s", t.name, n.row, tostring(msg))) end
                end
                -- names added to an array of names (a milestone's ConstructRewards), unless already there
                for _, l in ipairs(t.lists or {}) do
                    local ok, msg = pcall(function()
                        local data = rows[l.row]
                        if not data then error("row not found") end
                        local parent, werr = walk(data, l.steps, #l.steps - 1)
                        if not parent then error(werr) end
                        local field = l.steps[#l.steps][2]
                        local before = nameList(parent[field])
                        local target, have = {}, {}
                        for i, v in ipairs(before) do target[i] = v; have[v] = true end
                        for _, v in ipairs(l.add) do
                            if not have[v] then target[#target + 1] = v; have[v] = true end
                        end
                        setNameList(parent, field, target)
                        undo[#undo + 1] = { t.path, function() setNameList(parent, field, before) end }
                    end)
                    if ok then done = done + 1 else failed = failed + 1; log(string.format("failed %s %s: %s", t.name, l.row, tostring(msg))) end
                end
            end
        end
    end
    state.undo[fid], state.applied[fid] = undo, true
    log(string.format("%s: applied %d changes, %d failed (%s)", fid, done, failed, table.concat(where, ", ")))
end

local function restoreFeature(fid)
    local same, skipped = {}, {}
    local undo = state.undo[fid] or {}
    for i = #undo, 1, -1 do
        local path, fn = undo[i][1], undo[i][2]
        if same[path] == nil then
            local dt = findTable(path, false)
            same[path] = dt ~= nil and (addressOf(dt) or "unknown") == state.tables[path]
        end
        if same[path] then
            pcall(fn)
        else
            skipped[path] = true          -- the table was reloaded since; the new copy is vanilla already
        end
    end
    state.undo[fid], state.applied[fid] = {}, false
    local names = {}
    for path in pairs(skipped) do names[#names + 1] = path:match("([^%.]+)$") end
    log(fid .. ": restored vanilla values" .. (#names > 0 and (" (reloaded, left as is: " .. table.concat(names, ", ") .. ")") or ""))
end

local function applySet(set)
    for _, f in ipairs(FEATURES) do
        local want = (set or {})[f.id] == true
        if not OWNS_TABLES[f.id] then
            -- no tables: a live feature's script reads loaded.set (isActive) on its own
        elseif want and not state.applied[f.id] then
            applyFeature(f.id)
        elseif not want and state.applied[f.id] then
            restoreFeature(f.id)
        end
    end
end

-- ------------------------------------------------------------------ worlds: loading, new worlds, choices

local loaded = nil              -- {slot, set}: the world that is loaded and the features it was loaded with

-- A choice made on the new-game screen, before the world (and its save slot) exists: {set, existing}, where
-- existing lists the slots that already had a save file at the time.
local pending = nil
local newWorldHandled = {}      -- slot -> true once this load of a new world was handled (reset in the main menu)

local function existingSaves()
    local existing = {}
    for i = 0, 63 do
        if saveExists("World_" .. i) then existing["World_" .. i] = true end
    end
    return existing
end

-- First load of a world that has no save yet: store the new-game choice for its slot (nothing on if no choice was
-- made, which also clears a stale entry left by a deleted world that used the same slot).
local function handleNewWorld(slot, when)
    if not slot or newWorldHandled[slot] then return end
    local isNew = not saveExists(slot) or (pending ~= nil and not pending.existing[slot])
    if not isNew then return end
    newWorldHandled[slot] = true
    local set = pending and copySet(pending.set) or {}
    local worlds = readWorlds()
    worlds[slot] = set
    writeWorlds(worlds)
    pending = nil
    log(string.format("new world in %s (%s): %s, as set on the new-game screen", slot, when, describe(set)))
end

local function loadWorld(slot, when)
    handleNewWorld(slot, when)
    local set = readWorlds()[slot] or {}
    loaded = { slot = slot, set = copySet(set) }
    log(string.format("%s: world %s runs with %s", when, slot, describe(set)))
    applySet(set)
end

-- the value a settings row shows: saved for the loaded world, or in menus the choice for the next new world
local function featureValue(fid)
    local slot = getActiveSlot()
    if slot then return (readWorlds()[slot] or {})[fid] == true end
    return pending ~= nil and pending.set[fid] == true
end

-- store a choice; in a loaded world a table feature applies from the next load, a live feature at once
local function setFeature(fid, value, source)
    local slot = getActiveSlot()
    if slot then
        local worlds = readWorlds()
        local set = worlds[slot] or {}
        local now = isLive(fid) and loaded ~= nil and loaded.slot == slot
        if (set[fid] == true) == value and not (now and (loaded.set[fid] == true) ~= value) then return end
        set[fid] = value or nil
        worlds[slot] = set
        writeWorlds(worlds)
        if now then loaded.set[fid] = value or nil end
        log(string.format("%s: %s %s for %s (saved; %s)", source, fid, value and "ON" or "off", slot,
            not now and "applies when the world is next loaded"
            or OWNS_TABLES[fid] and "applies now; its table changes when the world is next loaded"
            or "applies now"))
    else
        if pending == nil then pending = { set = {}, existing = existingSaves() } end
        if (pending.set[fid] == true) == value then return end
        pending.set[fid] = value or nil
        log(string.format("%s: %s %s for the next new world (saved for its slot when it first loads)", source, fid,
            value and "ON" or "off"))
    end
end

-- true when the loaded world's saved value of feature fid (or of any feature, without fid) differs from what its
-- tables run with: the value the world loaded with for a table feature, the applied state for a live feature's
-- tables. A live feature without tables never needs a reload.
local function needsReload(fid)
    local slot = getActiveSlot()
    if not slot or not loaded or loaded.slot ~= slot then return false end
    local stored = readWorlds()[slot] or {}
    for _, f in ipairs(FEATURES) do
        if fid == nil or f.id == fid then
            local want = stored[f.id] == true
            if not f.live and want ~= (loaded.set[f.id] == true) then return true end
            if f.live and OWNS_TABLES[f.id] and want ~= (state.applied[f.id] == true) then return true end
        end
    end
    return false
end

-- true while the loaded world runs with feature fid (live features check this themselves)
local function isActive(fid)
    return loaded ~= nil and loaded.set[fid] == true
end

-- true while the world runs with feature fid's table changes: for a feature that owns tables, while they are in
-- (a live feature switched in a loaded world catches up on the next load); otherwise while it is active. The
-- Logistics Hubs follow this (unlocks.lua): they show in the build menu only while their feature's tables are in.
local function isLoadedWith(fid)
    if OWNS_TABLES[fid] then return loaded ~= nil and state.applied[fid] == true end
    return isActive(fid)
end

-- ------------------------------------------------------------------ live readout

local function sameAmounts(have, list)
    local n = 0
    for _, kv in ipairs(list) do
        if have[kv[1]] ~= kv[2] then return false end
        n = n + 1
    end
    for _ in pairs(have) do n = n - 1 end
    return n == 0
end

-- Values returned by a called UFunction come back either as Lua tables (UE4SS copies non-trivial return values) or
-- as UE4SS objects; accept both, and read struct fields directly or through :get().
local function eachElement(arr, fn)
    if type(arr) == "table" then
        for _, v in ipairs(arr) do fn(v) end
    else
        arr:ForEach(function(_, e) fn(e:get()) end)
    end
end

local function eachEntry(map, fn)
    if type(map) == "table" then
        for k, v in pairs(map) do fn(asText(k), v) end
    else
        map:ForEach(function(k, v) fn(asText(k:get()), v:get()) end)
    end
end

local function field(obj, name)
    local ok, v = pcall(function() return obj[name] end)
    if ok and v ~= nil then return v end
    ok, v = pcall(function() return obj:get()[name] end)
    if ok then return v end
    return nil
end

local function shape(v)
    if type(v) == "table" then
        local keys = {}
        for k, x in pairs(v) do
            keys[#keys + 1] = tostring(k) .. ":" .. type(x)
            if #keys >= 12 then break end
        end
        return "table {" .. table.concat(keys, ", ") .. "}"
    elseif type(v) == "userdata" then
        local name = "?"
        pcall(function() name = v:type() end)
        return "userdata " .. tostring(name)
    end
    return type(v) .. " " .. tostring(v)
end

local function tableReport(out)
    for _, t in ipairs(EDITS.tables) do
        local rows, err, dt = loadRows(t.path)
        if not rows then
            out(err)
        else
            local tag = string.format("[%s %s]", t.feature, state.applied[t.feature] and "applied" or "vanilla")
            local e = t.values and t.values[1]
            if e and rows[e.row] then
                local parent = walk(rows[e.row], e.steps, #e.steps - 1)
                if parent then
                    out(string.format("table %s %s = %s (vanilla %s, hardcore %s) %s at %s", t.name, e.row,
                        tostring(parent[e.steps[#e.steps][2]]), tostring(e.vanilla), tostring(e.value), tag,
                        hex(addressOf(dt))))
                end
            end
            local m = t.maps and t.maps[1]
            if m and rows[m.row] then
                local map = walk(rows[m.row], m.steps, #m.steps)
                out(string.format("table %s %s = %s (vanilla %s, hardcore %s) %s at %s", t.name, m.row,
                    formatEntries(map and mapEntries(map)), formatEntries(m.vanilla), formatEntries(m.target), tag,
                    hex(addressOf(dt))))
            end
            for _, n in ipairs(t.names or {}) do
                local parent = rows[n.row] and walk(rows[n.row], n.steps, #n.steps - 1)
                out(string.format("table %s %s %s = %s (shipped %s, with the feature %s) %s at %s", t.name, n.row,
                    n.steps[#n.steps - 1] and tostring(n.steps[#n.steps - 1][2]):match("^[^_]+") or "",
                    parent and tostring(asText(parent[n.steps[#n.steps][2]])) or "row not found", n.vanilla, n.value,
                    tag, hex(addressOf(dt))))
            end
            for _, l in ipairs(t.lists or {}) do
                local parent = rows[l.row] and walk(rows[l.row], l.steps, #l.steps - 1)
                out(string.format("table %s %s %s = {%s} (the feature adds %s) %s at %s", t.name, l.row,
                    l.steps[#l.steps][2], parent and table.concat(nameList(parent[l.steps[#l.steps][2]]), ", ")
                    or "row not found", table.concat(l.add, ", "), tag, hex(addressOf(dt))))
            end
        end
    end
end

-- what the game's delivery system (which keeps its own copy of the delivery table) is asking for right now
local function deliveryReport(out)
    local okDs, ds = pcall(FindFirstOf, "DeliverySystem")
    if not okDs or not ds or not ds:IsValid() then out("deliveries: no delivery system in this map"); return end
    local okPc, pc = pcall(FindFirstOf, "FarMechPlayerController")
    if not okPc or not pc or not pc:IsValid() then out("deliveries: no player controller yet"); return end
    local okCall, list = pcall(function() return ds:GetAvailableDeliveries(pc) end)
    if not okCall or list == nil then out("deliveries: could not ask the delivery system: " .. tostring(list)); return end
    local edits = {}
    for _, t in ipairs(EDITS.tables) do
        if t.name == "DT_Deliveries" then
            for _, m in ipairs(t.maps or {}) do edits[m.row] = m end
        end
    end
    local counts, lines, described = { hardcore = 0, vanilla = 0, other = 0, untouched = 0, unreadable = 0 }, {}, false
    local okEach, eachErr = pcall(eachElement, list, function(d)
        local id = asText(field(d, "DeliveryId"))
        local resources = field(d, "Resources")
        if not id or resources == nil then
            counts.unreadable = counts.unreadable + 1
            if not described then
                described = true
                out("deliveries: cannot read an entry; the list is " .. shape(list) .. ", an entry is " .. shape(d))
            end
            return
        end
        local have, parts = {}, {}
        local okRes, resErr = pcall(eachEntry, resources, function(name, amounts)
            local total, remaining = field(amounts, "TotalRequiredAmount"), field(amounts, "RemainingRequiredAmount")
            have[name] = total
            parts[#parts + 1] = string.format("%s %s/%s", name,
                tostring((tonumber(total) or 0) - (tonumber(remaining) or 0)), tostring(total))
        end)
        if not okRes then parts[#parts + 1] = "(could not read the amounts: " .. tostring(resErr) .. ")" end
        local e, verdict = edits[id], "not changed by the mod"
        if e then
            if sameAmounts(have, e.target) then verdict = "hardcore"
            elseif sameAmounts(have, e.vanilla) then verdict = "vanilla"
            else verdict = "other" end
            counts[verdict] = counts[verdict] + 1
        else
            counts.untouched = counts.untouched + 1
        end
        lines[#lines + 1] = string.format("  %s: %s (%s)", id, table.concat(parts, ", "), verdict)
    end)
    if not okEach then out("deliveries: could not read the list: " .. tostring(eachErr)); return end
    out(string.format("deliveries the game is asking for: %d with hardcore amounts, %d vanilla, %d other, %d not changed by the mod, %d unreadable",
        counts.hardcore, counts.vanilla, counts.other, counts.untouched, counts.unreadable))
    for i = 1, math.min(#lines, 8) do out(lines[i]) end
end

local extraReports = {}        -- report functions added by the feature scripts (api.addReport)
local extraCommands = {}       -- console sub-commands added by the feature scripts (api.addCommand)
local mapListeners = {}        -- called with the map name after every map load (api.onMapLoaded)
local leavingListeners = {}    -- called before every map load, while the old map still exists (api.onMapLeaving)

local function report(out)
    local slot = getActiveSlot()
    out(string.format("world %s (game instance slot %s): saved %s; running with %s; new-game choice %s",
        tostring(slot or "none"), tostring(gameInstanceSlot() or "none"),
        slot and describe(readWorlds()[slot] or {}) or "-",
        loaded and describe(loaded.set) or "nothing (no world loaded)",
        pending and describe(pending.set) or "none"))
    local ok, err = pcall(tableReport, out)
    if not ok then out("table readout failed: " .. tostring(err)) end
    ok, err = pcall(deliveryReport, out)
    if not ok then out("delivery readout failed: " .. tostring(err)) end
    for _, fn in ipairs(extraReports) do
        ok, err = pcall(fn, out)
        if not ok then out("readout failed: " .. tostring(err)) end
    end
end

-- ------------------------------------------------------------------ hooks and console command

local function isMenuMap(name) return name:find("/Game/Levels/MainMenu/", 1, true) ~= nil end
local function isGameplayMap(name) return name:find("/Game/Levels/Main/", 1, true) ~= nil end
local lastMap = ""

-- Before a world loads: apply or restore for the slot about to load, so the world starts with the right tables.
local okPre, preErr = pcall(RegisterLoadMapPreHook, function(Engine, WorldContext, URL, PendingGame, Error)
    for _, fn in ipairs(leavingListeners) do        -- drop pointers into the map that is about to go
        local okListener, listenerErr = pcall(fn)
        if not okListener then log("map-leaving listener failed: " .. tostring(listenerErr)) end
    end
    local ok, err = pcall(function()
        local target = nil
        pcall(function() target = asText(URL:get().Map) end)
        local goingToWorld
        if target and target ~= "" then
            goingToWorld = isGameplayMap(target)
        else
            goingToWorld = isMenuMap(lastMap)          -- from the main menu the only way on is into a world
        end
        if not goingToWorld then return end
        local slot = gameInstanceSlot()
        if not slot then
            log("loading a world, but the game instance has no save slot yet; applying after the load")
            return
        end
        loadWorld(slot, "before loading")
    end)
    if not ok then log("load-map pre hook failed: " .. tostring(err)) end
end)
if not okPre then log("no load-map pre hook (" .. tostring(preErr) .. "); changes are applied after the map loads") end

RegisterLoadMapPostHook(function(Engine, World)
    local name = ""
    pcall(function() name = World:get():GetFullName() end)
    lastMap = name
    for _, fn in ipairs(mapListeners) do
        local okListener, listenerErr = pcall(fn, name)
        if not okListener then log("map listener failed: " .. tostring(listenerErr)) end
    end
    local gameplay = isGameplayMap(name)
    if gameplay then
        local slot = getActiveSlot()
        if slot and (loaded == nil or loaded.slot ~= slot) then
            loadWorld(slot, "after loading (deliveries follow from the next load)")
        elseif slot then
            applySet(loaded.set)
            log(string.format("map loaded: world %s runs with %s", slot, describe(loaded.set)))
        else
            log("map loaded (" .. name .. "), but the world's save slot is not known yet")
        end
        pending = nil         -- a new-game choice only applies to the world created right after it
    else
        if isMenuMap(name) then newWorldHandled = {} end
        loaded = nil
        applySet({})
        log("map loaded (" .. name .. "): no world, vanilla values")
    end
    gameDelay(5000, function()
        if not gameplay then return end
        if not getActiveSlot() then diagnoseSlot() end
        report(log)
    end)
end)

RegisterConsoleCommandHandler("hardcore", function(FullCommand, Parameters, Ar)
    local a1 = string.lower(Parameters[1] or "status")
    local a2 = Parameters[2] and string.lower(Parameters[2]) or nil
    local function out(msg)
        log(msg)
        pcall(function() Ar:Log(MOD .. msg) end)
    end
    local slot = getActiveSlot()
    if a1 == "check" then
        report(out)
    elseif a1 == "timing" then
        -- how long each script loop's runs take (they run inside game frames)
        if a2 == "reset" then
            for _, st in ipairs(loopStats) do st.runs, st.total, st.max, st.slow = 0, 0, 0, 0 end
            out("timing: counters reset")
            return true
        end
        for _, st in ipairs(loopStats) do
            out(string.format("timing: %s %s: %d runs, average %.2f ms, longest %.1f ms, last %.2f ms, %d of "
                .. "%d ms or more", st.what, st.every > 0 and ("every " .. st.every .. " ms") or "(when asked)", st.runs,
                st.runs > 0 and st.total / st.runs or 0, st.max, st.last, st.slow, SLOW_MS))
        end
        out("timing: hardcore timing reset  clears the counters")
    elseif extraCommands[a1] then
        local ok, err = pcall(extraCommands[a1], out, a2)
        if not ok then out(a1 .. " failed: " .. tostring(err)) end
    elseif a1 == "on" or a1 == "off" or (FEATURE[a1] and (a2 == "on" or a2 == "off")) then
        if not slot then
            out("no world is loaded")
            return true
        end
        if FEATURE[a1] then
            setFeature(a1, a2 == "on", "console")
        else
            for _, f in ipairs(FEATURES) do setFeature(f.id, a1 == "on", "console") end
        end
        out(string.format("saved for %s: %s.%s", slot, describe(readWorlds()[slot] or {}),
            needsReload() and " Save and reload the world to apply it." or ""))
    else
        local ids, cmds = {}, { "check", "timing", "on", "off", "<feature> on", "<feature> off" }
        for _, f in ipairs(FEATURES) do ids[#ids + 1] = f.id end
        for name in pairs(extraCommands) do cmds[#cmds + 1] = name end
        out(string.format("world %s: saved %s; running with %s (edits built %s)", tostring(slot or "none"),
            slot and describe(readWorlds()[slot] or {}) or "-", loaded and describe(loaded.set) or "nothing",
            tostring(EDITS.generated)))
        if a1 ~= "status" then
            out("usage: hardcore [" .. table.concat(cmds, " | ") .. "]; features: " .. table.concat(ids, ", "))
        end
    end
    return true
end)

local api = {
    log = log, asText = asText, makeName = makeName, features = FEATURES, mode = EDITS.mode,
    trampling = EDITS.trampling or {},
    storage = EDITS.storage or {},
    hub = EDITS.hub or {},
    drones = EDITS.drones or {},
    unlocks = EDITS.unlocks or {},
    getActiveSlot = getActiveSlot, featureValue = featureValue, setFeature = setFeature, needsReload = needsReload,
    isActive = isActive, isLoadedWith = isLoadedWith,
    -- true while a world is loaded (from this script's own map hooks; costs nothing, unlike getActiveSlot, which
    -- looks objects up)
    worldLoaded = function() return loaded ~= nil end,
    recordTiming = recordTiming,   -- recordTiming(what, ms): time work that a hook starts
    setAllFeatures = function(value, source)
        for _, f in ipairs(FEATURES) do setFeature(f.id, value, source) end
    end,
    addReport = function(fn) extraReports[#extraReports + 1] = fn end,
    addCommand = function(name, fn) extraCommands[name] = fn end,
    onMapLoaded = function(fn) mapListeners[#mapListeners + 1] = fn end,
    onMapLeaving = function(fn) leavingListeners[#leavingListeners + 1] = fn end,
    loop = gameLoop,               -- loop(ms, what, fn): fn every ms on the game thread, errors logged as "<what> failed"
}
local okUi, uiErr = pcall(function() require("ui")(api) end)
if not okUi then log("settings rows disabled: " .. tostring(uiErr)) end
if EDITS.mode then
    local okCards, cardsErr = pcall(function() require("cards")(api) end)
    if not okCards then log("playstyle card disabled: " .. tostring(cardsErr)) end
end
if FEATURE.trampling then
    local okTrample, trampleErr = pcall(function() require("trample")(api) end)
    if not okTrample then log("crop trampling disabled: " .. tostring(trampleErr)) end
end
if EDITS.unlocks and #EDITS.unlocks > 0 then
    local okUnlocks, unlocksErr = pcall(function() require("unlocks")(api) end)
    if not okUnlocks then log("building unlocks disabled: " .. tostring(unlocksErr)) end
end
if FEATURE.storage then
    local okStorage, storageErr = pcall(function() require("storage")(api) end)
    if not okStorage then log("local storage disabled: " .. tostring(storageErr)) end
end
if EDITS.drones and EDITS.drones.stations and #EDITS.drones.stations > 0 then
    local okDrones, dronesErr = pcall(function() require("drones")(api) end)
    if not okDrones then log("drone stations disabled: " .. tostring(dronesErr)) end
end

log(string.format("loaded version %s: %d features, %d tables, worlds file %s", tostring(EDITS.version or "?"),
    #FEATURES, #EDITS.tables, WORLDS_FILE))
